window.KH_SURA(78, {"sura": "النبأ", "n": 78, "ayat": {"1": "عَمَّ يَتَسَاءَلُونَ", "2": "عَنِ النَّبَإِ الْعَظِيمِ", "3": "الَّذِي هُمْ فِيهِ مُخْتَلِفُونَ", "4": "كَلَّا سَيَعْلَمُونَ", "5": "ثُمَّ كَلَّا سَيَعْلَمُونَ", "6": "أَلَمْ نَجْعَلِ الْأَرْضَ مِهَادًا", "7": "وَالْجِبَالَ أَوْتَادًا", "8": "وَخَلَقْنَاكُمْ أَزْوَاجًا", "9": "وَجَعَلْنَا نَوْمَكُمْ سُبَاتًا", "10": "وَجَعَلْنَا اللَّيْلَ لِبَاسًا", "11": "وَجَعَلْنَا النَّهَارَ مَعَاشًا", "12": "وَبَنَيْنَا فَوْقَكُمْ سَبْعًا شِدَادًا", "13": "وَجَعَلْنَا سِرَاجًا وَهَّاجًا", "14": "وَأَنْزَلْنَا مِنَ الْمُعْصِرَاتِ مَاءً ثَجَّاجًا", "15": "لِنُخْرِجَ بِهِ حَبًّا وَنَبَاتًا", "16": "وَجَنَّاتٍ أَلْفَافًا", "17": "إِنَّ يَوْمَ الْفَصْلِ كَانَ مِيقَاتًا", "18": "يَوْمَ يُنْفَخُ فِي الصُّورِ فَتَأْتُونَ أَفْوَاجًا", "19": "وَفُتِحَتِ السَّمَاءُ فَكَانَتْ أَبْوَابًا", "20": "وَسُيِّرَتِ الْجِبَالُ فَكَانَتْ سَرَابًا", "21": "إِنَّ جَهَنَّمَ كَانَتْ مِرْصَادًا", "22": "لِلطَّاغِينَ مَآبًا", "23": "لَابِثِينَ فِيهَا أَحْقَابًا", "24": "لَا يَذُوقُونَ فِيهَا بَرْدًا وَلَا شَرَابًا", "25": "إِلَّا حَمِيمًا وَغَسَّاقًا", "26": "جَزَاءً وِفَاقًا", "27": "إِنَّهُمْ كَانُوا لَا يَرْجُونَ حِسَابًا", "28": "وَكَذَّبُوا بِآيَاتِنَا كِذَّابًا", "29": "وَكُلَّ شَيْءٍ أَحْصَيْنَاهُ كِتَابًا", "30": "فَذُوقُوا فَلَنْ نَزِيدَكُمْ إِلَّا عَذَابًا", "31": "إِنَّ لِلْمُتَّقِينَ مَفَازًا", "32": "حَدَائِقَ وَأَعْنَابًا", "33": "وَكَوَاعِبَ أَتْرَابًا", "34": "وَكَأْسًا دِهَاقًا", "35": "لَا يَسْمَعُونَ فِيهَا لَغْوًا وَلَا كِذَّابًا", "36": "جَزَاءً مِنْ رَبِّكَ عَطَاءً حِسَابًا", "37": "رَبِّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا الرَّحْمَنِ لَا يَمْلِكُونَ مِنْهُ خِطَابًا", "38": "يَوْمَ يَقُومُ الرُّوحُ وَالْمَلَائِكَةُ صَفًّا لَا يَتَكَلَّمُونَ إِلَّا مَنْ أَذِنَ لَهُ الرَّحْمَنُ وَقَالَ صَوَابًا", "39": "ذَلِكَ الْيَوْمُ الْحَقُّ فَمَنْ شَاءَ اتَّخَذَ إِلَى رَبِّهِ مَآبًا", "40": "إِنَّا أَنْذَرْنَاكُمْ عَذَابًا قَرِيبًا يَوْمَ يَنْظُرُ الْمَرْءُ مَا قَدَّمَتْ يَدَاهُ وَيَقُولُ الْكَافِرُ يَالَيْتَنِي كُنْتُ تُرَابًا"}, "units": [{"aya": 0, "title": "قوله: {يتساءلون}", "mawsua": {"taliq": 6979, "masala": "قوله: {يتساءلون}", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يريد: جميع العالم", "ashab": "", "athar": []}, {"n": 2, "t": "أن يراد بالضمير: الكفار من قريش", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 6979, "mi": 1, "aya": 0, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "8/ 512", "qawl": "", "nass": "أن يريد: جميع العالم", "qawaid": [], "tabi": ""}, {"taliq": 6979, "mi": 1, "aya": 0, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "8/ 512", "qawl": "", "nass": "و {النبأ العظيم} قال قوم: هو الشرع الذي جاء به محمد صلى الله عليه وسلم", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 2, "title": "في المعني بالنبأ العظيم", "tabari": {"page": "24/5", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "أريد به القرآن", "taqdim": 0, "n_athar": 1, "qailun": [["مجاهد", "تابعي"]], "athar": []}, {"n": 2, "t": "عنى به البعث", "taqdim": 0, "n_athar": 3, "qailun": [["قتادة", "تابعي"], ["ابن زيد", "تابع التابعين"]], "athar": []}]}, "mawaqif": [{"taliq": 6980, "mi": 0, "aya": 3, "alam": "ابن جرير", "fil": "بين", "kind": "بيان", "ref": "24/ 7 - 8", "qawl": "مقاتل", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 6980, "mi": 0, "aya": 3, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "8/ 513", "qawl": "", "nass": "وقرأ السبعة، والحسن، وأبو جعفر، وشيبة، والأعمش: {كلا سيعلمون} بالياء في الموضعين على ذكر الغائب، فظاهر الكلام أنه رد على الكفار في تكذيبهم وعيد لهم في المستقبل، وكرر الزجر تأكيدا، وقال الضحاك: المعنى: {كلا سيعلمون} يعني: الكفار على جهة الوعيد، {ثم كلا سيعلمون} يعني: المؤمنين على جهة الوعد. وقرأ ابن عامر فيما روى عنه مالك بن دينار والحسن بخلاف: (كلا ستعلمون) بالتاء في الموضعين على مخاطبة الحاضر، كأنه تعالى يقول: قل لهم، يا محمد، وكرر عليهم الزجر والوعيد تأكيدا. وكل تأويل في هذه القراءة غير هذا فمتعسف. وقرأ قوم: {كلا سيعلمون} بالياء على جهة الرد والوعيد للكفار، (ثم كلا ستعلمون) بالتاء من فوق على جهة الرد على الكفار والوعد للمؤمنين", "qawaid": [], "tabi": ""}], "mushid": {"i": 1, "imgs": ["078_001_1.png"], "pages": [543], "n": 2, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 14, "title": "في المعني بالمعصرات", "tabari": {"page": "24/11", "sarih": 1, "tarjih": "وأولى الأقوال في ذلك بالصواب أن يقال: إن الله أخبر أنه أنزل من المعصرات - وهى التي قد تحلبت بالماء من السحاب - ماء.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "عنى بها الرياح التي تعصر في هبوبها", "taqdim": 0, "n_athar": 6, "qailun": [["ابن عباس", "صحابي"], ["عكرمة", "تابعي"], ["مجاهد", "تابعي"], ["قتادة", "تابعي"], ["ابن زيد", "تابع التابعين"]], "athar": [80852, 80853, 80854, 80861, 80862, 80863, 80866, 80870, 80873, 80874, 80875, 80876, 80879, 80880, 80884]}, {"n": 2, "t": "بل هي السحاب التي تتحلب بالمطر ولما تمطر، كالمرأة المعصر التي قد دنا أوان حيضها ولم تحض", "taqdim": 0, "n_athar": 2, "qailun": [["سفيان", "تابع التابعين"], ["ابن عباس", "صحابي"]], "athar": [80861, 80862, 80863, 80872, 80874, 80875, 80883]}, {"n": 3, "t": "بل هي السماء", "taqdim": 0, "n_athar": 3, "qailun": [["قتادة", "تابعي"]], "athar": [80852, 80853, 80870, 80879, 80880]}]}, "mawaqif": [{"taliq": 6982, "mi": 1, "aya": 14, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 424", "qawl": "الأول", "nass": "وقرأ ابن الزبير، وابن عباس، والفضل بن عباس، وقتادة، وعكرمة: (وأنزلنا بالمعصرات)، فهذا يقوي أنه أراد الرياح", "qawaid": [], "tabi": ""}, {"taliq": 6982, "mi": 1, "aya": 14, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "8/ 514 - 515", "qawl": "الجمهور", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 6982, "mi": 1, "aya": 14, "alam": "ابن كثير", "fil": "وجه", "kind": "توجيه", "ref": "14/ 228", "qawl": "الأول", "nass": "ومعنى هذا القول: أنها تستدر المطر من السحاب", "qawaid": [], "tabi": ""}, {"taliq": 6982, "mi": 1, "aya": 14, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "24/ 14", "qawl": "الثاني", "nass": "وأولى الأقوال في ذلك بالصواب أن يقال: إن الله أخبر أنه أنزل من المعصرات، وهي التي قد تحلبت بالماء من السحاب ماء، وإنما قلنا ذلك أولى بالصواب لأن القول في ذلك على أحد الأقوال الثلاثة التي ذكرت، والرياح لا ماء فيها فينزل منها، وإنما ينزل بها، وكان يصح أن تكون الرياح لو كانت القراءة: (وأنزلنا بالمعصرات)، فلما كانت القراءة: {من المعصرات} علم أن المعني بذلك ما وصفت، فإن ظن ظان أن الباء قد تعقب في مثل هذا الموضع", "qawaid": ["الدلالة العقلية", "اللغة", "القرآن والنظائر"], "tabi": ""}, {"taliq": 6982, "mi": 1, "aya": 14, "alam": "ابن كثير", "fil": "وبنحوه", "kind": "موافقة", "ref": "", "qawl": "", "nass": "والأظهر أن المراد بالمعصرات: السحاب، كما قال الله تعالى: {الله الذي يرسل الرياح فتثير سحابا فيبسطه في السماء كيف يشاء ويجعله كسفا فترى الودق يخرج من خلاله} [الروم: 48]، أي: من بينه", "qawaid": ["القرآن والنظائر"], "tabi": "ابن جرير"}, {"taliq": 6982, "mi": 1, "aya": 14, "alam": "ابن كثير", "fil": "انتقد", "kind": "نقد", "ref": "", "qawl": "الثالث", "nass": "وهذا قول غريب", "qawaid": [], "tabi": ""}], "mushid": {"i": 2, "imgs": ["078_002_1.png"], "pages": [543], "n": 3, "rajih": [2], "daif": [], "match": true}, "mawsua": {"taliq": 6982, "masala": "المراد بالمعصرات", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "الرياح", "ashab": "", "athar": []}, {"n": 2, "t": "السحاب", "ashab": "", "athar": []}, {"n": 3, "t": "السماء", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن كثير", "w"]], "2": [["ابن جرير", "r"], ["ابن كثير", "r"]], "3": [["ابن كثير", "d"]]}, "t": {"2": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["الدلالة العقلية", "اللغة", "القرآن والنظائر"], "ابن كثير": ["القرآن والنظائر"]}, "rulesD": {}}}, {"aya": 14, "title": "تأويل: ﴿ماء ثجاجا﴾", "tabari": {"page": "24/15", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "وأما قوله: ﴿ماء ثجاجا﴾. يقول: ماء منصبا يتبع بعضه بعضا. كتج دماء البدن، وذلك سفكها.", "taqdim": 1, "n_athar": 5, "qailun": [["ابن عباس", "صحابي"], ["مجاهد", "تابعي"], ["قتادة", "تابعي"], ["أبي جعفر عن الربيع", "تابعي"]], "athar": [80852, 80853, 80854, 80861, 80862, 80863, 80866, 80870, 80874, 80875, 80876, 80879, 80880]}, {"n": 2, "t": "عنى بالثجاج الكثير", "taqdim": 0, "n_athar": 1, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 6983, "mi": 1, "aya": 14, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "24/ 14 - 15", "qawl": "الأول", "nass": "وأما قوله: {ماء ثجاجا} يقول: ماء منصبا يتبع بعضه بعضا، كثج دماء البدن، وذلك سفكها، وبنحو الذي قلنا في ذلك قال أهل التأويل", "qawaid": ["أقوال السلف", "اللغة", "القرآن والنظائر"], "tabi": ""}], "mawsua": {"taliq": 6983, "masala": "قوله: {ثجاجا}", "sigha": "في المسألة قولان", "nasib": "", "aqwal": [{"n": 1, "t": "منصبا متتابعا", "ashab": "", "athar": []}, {"n": 2, "t": "كثيرا", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"]]}, "t": {}, "gen": [], "rules": {"ابن جرير": ["أقوال السلف", "اللغة", "القرآن والنظائر"]}, "rulesD": {}}}, {"aya": 16, "title": "في واحد الألفاف", "tabari": {"page": "24/17", "sarih": 1, "tarjih": "والصواب من القول في ذلك أن الألفاف جمع لف أو لفيف، وذلك أن أهل التأويل مجمعون على أن معناه: ملتفة. واللفاء هي الغليظة، وليس الالتفاف من الغلظ في شيء، إلا أن يوجه إلى أنه غلظ الالتفاف، فيكون ذلك حينئذ وجها.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "واحدها: لف ولفيف. قال: وإن شئت كان الألفاف جمعا، واحده جمع أيضا، فتقول: جنة لفاء، وجنات لفاء . ثم يجمع اللف ألفافا", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "لم نسمع ب: شجرة لفة. ولكن واحدها لفاء، وجمعها لف، وجمع لف ألفاف، فهو جمع الجمع", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 19, "title": "تأويل: ﴿وفتحت السماء فكانت أبوابا﴾", "tabari": {"page": "24/19", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿وفتحت السماء فكانت أبوابا﴾. يقول تعالى ذكره: وشققت السماء فصدعت، فكانت طرقا، وكانت من قبل شدادا لا فطور فيها ولا صدوع.", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "معنى ذلك: وفتحت السماء فكانت قطعا كقطع الخشب المشققة لأبواب الدور والمساكن. قالوا: ومعنى الكلام: وفتحت السماء فكانت قطعا كالأبواب. فلما أسقطت الكاف صارت الأبواب الخبر. كما يقال في الكلام: كان عبد الله أسدا: كالأسد", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 23, "title": "في مبلغ مدة الحقب", "tabari": {"page": "24/23", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "مدته ثلاثمائة سنة", "taqdim": 0, "n_athar": 1, "qailun": [["بشير بن كعب", ""]], "athar": [80934]}, {"n": 2, "t": "بل مدة الحقب الواحد ثمانون سنة", "taqdim": 0, "n_athar": 7, "qailun": [["سالم بن أبي الجعد", "تابعي"], ["أبي هريرة", "صحابي"], ["ابن عباس", "صحابي"], ["سعيد بن جبير", "تابعي"], ["قتادة", "تابعي"], ["الربيع بن أنس", "تابعي"]], "athar": [80921, 80927, 80928, 80930, 80931, 80935, 80942, 80944]}, {"n": 3, "t": "الحقب الواحد سبعون ألف سنة", "taqdim": 0, "n_athar": 3, "qailun": [["قول الله", ""], ["الحسن", "تابعي"], ["خالد بن معدان", "تابعي"]], "athar": [80937, 80938, 80939, 80940, 80941]}]}, "mawaqif": [{"taliq": 6987, "mi": 1, "aya": 23, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "24/ 26 بتصرف", "qawl": "", "nass": "الذي قاله قتادة والربيع بن أنس في ذلك أصح. فإن قيل: فما للكفار عند الله عذاب إلا أحقابا. قيل: إن الربيع وقتادة قد قالا: إن هذه الأحقاب لا انقضاء لها ولا انقطاع. وقد يحتمل أن يكون معنى ذلك: {لابثين فيها أحقابا}، في هذا النوع من العذاب هو أنهم: {لا يذوقون فيها بردا ولا شرابا إلا حميما وغساقا}، فإذا انقضت تلك الأحقاب صار لهم من العذاب أنواع غير ذلك، كما قال -جل ثناؤه- في كتابه: {وإن للطاغين لشر مآب جهنم يصلونها فبئس المهاد هذا فليذوقوه حميم وغساق وآخر من شكله أزواج} [ص: 55 - 58]، وهذا القول عندي أشبه بمعنى الآية", "qawaid": [], "tabi": ""}, {"taliq": 6987, "mi": 1, "aya": 23, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "8/ 518", "qawl": "", "nass": "اللازم أن الله تعالى أخبر عن الكفار أنهم يلبثون أحقابا، كلما مر حقب جاء غيره إلى ما لا نهاية", "qawaid": ["السياق"], "tabi": ""}, {"taliq": 6987, "mi": 1, "aya": 23, "alam": "ابن تيمية", "fil": "ذكر", "kind": "نقل", "ref": "6/ 453", "qawl": "", "nass": "وهذا الذي قاله الزجاج شاذ، خلاف ما عليه الأولون والآخرون، وهو خلاف ما دل عليه القرآن، فإن هذا يقتضي أنهم يبقون بعد الأحقاب فيها، ولكن لا يذوقون البرد والشراب حينئذ، وهذا باطل قطعا، ثم إذا ذاقوا البرد والشراب فهذا نعيم، فكيف يكونون معذبين فيها ذلك؟!", "qawaid": ["الدلالة العقلية", "الإجماع"], "tabi": ""}], "mushid": {"i": 3, "imgs": ["078_003_1.png"], "pages": [543], "n": 3, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 6987, "masala": "الموصوف باللبث أحقابا", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "الكفار", "ashab": "", "athar": []}, {"n": 2, "t": "عصاة المؤمنين. وكذا اختلف في مدة الحقب على أقوال: الأول: ألف شهر. الثاني: ثلاثون ألف سنة. الثالث: ثمانون سنة. الرابع: بضع وثمانون سنة. الخامس: أربعون سنة. السادس: ثلاثمائة سنة. السابع: ثمانون ألف سنة. الثامن: سبعون ألف سنة. التاسع: سبع عشرة ألف سنة. العاشر: أن الحقب لا حد له", "ashab": "", "athar": []}]}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 24, "title": "قوله: {بردا}", "mawsua": {"taliq": 6989, "masala": "قوله: {بردا}", "sigha": "في المسألة قولان", "nasib": "", "aqwal": [{"n": 1, "t": "برد الهواء", "ashab": "", "athar": []}, {"n": 2, "t": "النوم", "ashab": "", "athar": []}, {"n": 3, "t": "الراحة", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 6989, "mi": 1, "aya": 24, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "8/ 519", "qawl": "الأول", "nass": "فالذوق على هذين القولين مستعار", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 25, "title": "في معنى الغساق", "tabari": {"page": "24/28", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "هو ما سال من صديد أهل جهنم", "taqdim": 0, "n_athar": 11, "qailun": [["عطية ابن سعد", "تابعي"], ["إبراهيم وأبى رزين", ""], ["كما", ""], ["أبي رزين", "تابعي"], ["قتادة", "تابعي"], ["سفيان", "تابع التابعين"], ["إبراهيم", "تابعي"], ["ابن زيد", "تابع التابعين"]], "athar": [80959, 80960, 80961, 80966, 80967, 80971, 80972]}, {"n": 2, "t": "الغساق الزمهرير", "taqdim": 0, "n_athar": 5, "qailun": [["ابن عباس", "صحابي"], ["مجاهد", "تابعي"], ["الربيع", "تابعي"], ["أبي العالية", "تابعي"]], "athar": [80957, 80958, 80963, 80968, 80969]}, {"n": 3, "t": "هو المنتن، وهو بالطخارية", "taqdim": 0, "n_athar": 2, "qailun": [["عبد الله بن بريدة", "تابعي"], ["عبد الله بن عمرو", "صحابي"]], "athar": [80956, 80962]}]}, "mawaqif": [{"taliq": 6990, "mi": 1, "aya": 25, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "8/ 520", "qawl": "الأول", "nass": "يقال: غسق الجرح: إذا سال منه قيح ودم، وغسقت العين: إذا دمعت وإذا خرج قذاها", "qawaid": [], "tabi": ""}, {"taliq": 6990, "mi": 1, "aya": 25, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "24/ 31", "qawl": "", "nass": "والغساق عندي: هو الفعال، من قولهم: غسقت عين فلان: إذا سالت دموعها، وغسق الجرح: إذا سال صديده، ومنه قول الله: {ومن شر غاسق إذا وقب} [الفلق: 3] يعني بالغاسق: الليل إذا لبس الأشياء وغطاها، وإنما أريد بذلك هجومه على الأشياء هجوم السيل السائل، فإذا كان الغساق هو ما وصفت من الشيء السائل فالواجب أن يقال: الذي وعد الله هؤلاء القوم، وأخبر أنهم يذوقونه في الآخرة من الشراب، هو السائل من الزمهرير في جهنم، الجامع مع شدة برده النتن", "qawaid": [], "tabi": ""}], "mushid": {"i": 4, "imgs": ["078_004_1.png"], "pages": [543], "n": 3, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 6990, "masala": "الغساق", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "ما يسيل من جلود أهل النار من الصديد", "ashab": "", "athar": []}, {"n": 2, "t": "الزمهرير", "ashab": "", "athar": []}, {"n": 3, "t": "المنتن", "ashab": "", "athar": []}]}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 28, "title": "تأويل: ﴿وكذبوا بآياتنا كذابا﴾", "tabari": {"page": "24/35", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿وكذبوا بآياتنا كذابا﴾. يقول تعالى ذكره: وكذب هؤلاء الكفار بحججنا وأدلتنا تكذيبا. وقيل: ﴿كذابا﴾. ولم يقل: تكذيبا. تصديرا على فعله.", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "هذه لغة يمانية فصيحة، يقولون: كذبت به كذابا، وخرقت القميص خراقا. وكل (فعلت)، فمصدرها \"فعال\" في لغتهم مشددة. قال: وقال لى أعرابي مرة على المروة يستفتيني: آلحلق أحب إليك أم القصار؟ قال: وأنشدنى بعض بني كلاب :", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 34, "title": "تأويل: ﴿وكأسا دهاقا﴾", "tabari": {"page": "24/41", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿وكأسا دهاقا﴾. يقول: وكأسا ملأى متتابعة على شاربيها بكثرة وامتلاء. وأصله من الدهق، وهو متابعة الضغط على الإنسان بشدة وعنف، وكذلك الكأس الدهاق، متابعتها على شاربيها بكثرة وامتلاء.", "taqdim": 1, "n_athar": 12, "qailun": [["مسلم بن نسطاس", ""], ["ابن عباس", "صحابي"], ["ابن زيد", "تابع التابعين"], ["أبي هريرة", "صحابي"], ["الحسن", "تابعي"], ["مجاهد", "تابعي"], ["قتادة", "تابعي"]], "athar": [81014, 81015, 81016, 81017, 81018, 81019, 81020, 81022, 81024, 81025, 81026, 81029, 81034, 81036]}, {"n": 2, "t": "الدهاق الصافية", "taqdim": 0, "n_athar": 1, "qailun": [["عكرمة", "تابعي"]], "athar": []}, {"n": 3, "t": "بل هي المتتابعة", "taqdim": 0, "n_athar": 4, "qailun": [["معمر", "تابع التابعين"], ["مجاهد", "تابعي"], ["ابن عباس", "صحابي"]], "athar": [81015, 81016, 81017, 81018, 81019, 81020, 81022, 81026, 81029]}]}, "mawaqif": [{"taliq": 6994, "mi": 1, "aya": 34, "alam": "ابن جرير", "fil": "جمع", "kind": "توجيه", "ref": "24/ 39 - 42", "qawl": "الأول", "nass": "وقوله: {وكأسا دهاقا} يقول: وكأسا ملأى متتابعة على شاربيها بكثرة وامتلاء، وأصله من الدهق: وهو متابعة الضغط على الإنسان بشدة وعنف. وكذلك الكأس الدهاق: متابعتها على شاربيها بكثرة وامتلاء. وبنحو الذي قلنا في ذلك قال أهل التأويل", "qawaid": ["اللغة", "أقوال السلف"], "tabi": ""}], "mushid": {"i": 5, "imgs": ["078_005_1.png"], "pages": [544], "n": 3, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 6994, "masala": "قوله: {دهاقا}", "sigha": "في المسألة قولان", "nasib": "", "aqwal": [{"n": 1, "t": "ملأى", "ashab": "", "athar": []}, {"n": 2, "t": "متتابعة", "ashab": "", "athar": []}, {"n": 3, "t": "صافية", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "w"]]}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 38, "title": "في معنى الروح في هذا الموضع ﴿يوم يقوم الروح﴾", "tabari": {"page": "24/46", "sarih": 1, "tarjih": "والصواب من القول أن يقال: إن الله تعالى ذكره أخبر أن خلقه لا يملكون منه خطابا يوم يقوم الروح، والروح خلق من خلقه، وجائز أن يكون بعض هذه الأشياء التي ذكرت، والله أعلم أي ذلك هو، ولا خبر بشيء من ذلك أنه المعني به دون غيره يجب التسليم له، ولا حجة تدل عليه، وغير ضائر الجهل به.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "هو ملك من أعظم الملائكة خلقا", "taqdim": 0, "n_athar": 2, "qailun": [["ابن مسعود", "صحابي"], ["ابن عباس", "صحابي"]], "athar": [81053, 81054, 81055, 81056, 81057, 81058, 81059, 81081, 81082]}, {"n": 2, "t": "هو جبريل", "taqdim": 0, "n_athar": 3, "qailun": [["الضحاك", "تابعي"], ["الشعبي", "تابعي"]], "athar": [81062, 81063, 81065]}, {"n": 3, "t": "هو خلق من خلق الله في صورة بني آدم", "taqdim": 0, "n_athar": 6, "qailun": [["مجاهد", "تابعي"], ["الأعمش", "تابع التابعين"]], "athar": [81060, 81061, 81076, 81083]}, {"n": 4, "t": "هم بنو آدم", "taqdim": 0, "n_athar": 2, "qailun": [["قتادة", "تابعي"], ["الحسن", "تابعي"]], "athar": [81068, 81069, 81073, 81074, 81087]}, {"n": 5, "t": "قيل: ذلك أرواح بني آدم", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [81053, 81055, 81056, 81057, 81058, 81059, 81081, 81082]}, {"n": 6, "t": "هو القرآن", "taqdim": 0, "n_athar": 1, "qailun": [["ابن زيد", "تابع التابعين"]], "athar": [81075]}, {"n": 7, "t": "إنه يقوم سماطان", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 7000, "mi": 1, "aya": 38, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "14/ 236", "qawl": "الثاني", "nass": "ويستشهد لهذا القول بقوله: {نزل به الروح الأمين على قلبك لتكون من المنذرين} [الشعراء: 193 - 194]", "qawaid": [], "tabi": ""}, {"taliq": 7000, "mi": 1, "aya": 38, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "8/ 523 - 524", "qawl": "الخامس", "nass": "وقال ابن عباس، والحسن، وقتادة: الروح هنا اسم جنس، يراد به: أرواح بني آدم، والمعنى: يوم تقوم الأرواح في أجسادها إثر البعث والنشأة الآخرة، ويكون الجمع من الإنس والملائكة صفا، ولا يتكلم أحد هيبة وفزعا، {إلا من أذن له الرحمن} من ملك أو نبي، وكان أهلا أن يقول صوابا في ذلك الموطن", "qawaid": [], "tabi": ""}, {"taliq": 7000, "mi": 1, "aya": 38, "alam": "ابن كثير", "fil": "رجح", "kind": "ترجيح", "ref": "8/ 310", "qawl": "الرابع", "nass": "والأشبه -والله أعلم- أنهم بنو آدم", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}], "mushid": {"i": 6, "imgs": ["078_006_1.png"], "pages": [544], "n": 7, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 7000, "masala": "ما عنى الله بالروح", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "ملك من أعظم الملائكة", "ashab": "", "athar": []}, {"n": 2, "t": "جبريل", "ashab": "", "athar": []}, {"n": 3, "t": "خلق يشبه بني آدم", "ashab": "", "athar": []}, {"n": 4, "t": "بنو آدم", "ashab": "", "athar": []}, {"n": 5, "t": "أرواح بني آدم", "ashab": "", "athar": []}, {"n": 6, "t": "القرآن", "ashab": "", "athar": []}, {"n": 7, "t": "أنهم حفظة على الملائكة", "ashab": "", "athar": []}]}, "tags": {"m": {"4": [["ابن كثير", "r"]]}, "t": {"4": [["ابن كثير", "r"]]}, "gen": [], "rules": {"ابن كثير": ["لم يذكر مستندًا"]}, "rulesD": {}}}, {"aya": 38, "title": "تأويل: ﴿لا يتكلمون إلا من أذن له الرحمن﴾", "tabari": {"page": "24/51", "sarih": 0, "tarjih": "والصواب من القول في ذلك أن يقال: إن الله تعالى ذكره أخبر عن خلقه أنهم لا يتكلمون يوم يقوم الروح والملائكة صفا إلا من أذن له منهم في الكلام الرحمن وقال صوابا. فالواجب أن يقال كما أخبر، إذ لم يخبرنا في كتابه، ولا على لسان رسوله، أنه عنى بذلك نوعا من أنواع الصواب، والظاهر محتمل جميعه.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "﴿لا يتكلمون إلا من أذن له الرحمن﴾، قيل: إنهم يؤذن لهم في الكلام حين يمر بأهل النار إلى النار، وبأهل الجنة إلى الجنة.", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "﴿إلا من أذن له الرحمن﴾ بالتوحيد، ﴿وقال صوابا﴾ في الدنيا، فوحد الله", "taqdim": 0, "n_athar": 3, "qailun": [["ابن عباس", "صحابي"], ["مجاهد", "تابعي"], ["أبي صالح", "تابعي"]], "athar": [81053, 81055, 81056, 81057, 81058, 81059, 81060, 81061, 81070, 81081, 81082, 81083, 81086]}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 38, "title": "الوقت الذي يؤذن فيه بالكلام القول الصواب", "mawsua": {"taliq": 7002, "masala": "الوقت الذي يؤذن فيه بالكلام القول الصواب", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنه في الدنيا، كما ورد في قول من قال من السلف: هو قول لا إله إلا الله، والإذن يكون في الدنيا بالتوحيد", "ashab": "", "athar": []}, {"n": 2, "t": "أنه في الآخرة، والإذن كما أشير إليه في أثر عكرمة من طريق أبي عمرو", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 7002, "mi": 1, "aya": 38, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "24/ 52", "qawl": "", "nass": "والصواب من القول في ذلك: أن يقال: إن الله -تعالى ذكره- أخبر عن خلقه أنهم لا يتكلمون يوم يقوم الروح والملائكة صفا، إلا من أذن له منهم في الكلام الرحمن، وقال صوابا، فالواجب أن يقال كما أخبر إذ لم يخبرنا في كتابه، ولا على لسان رسوله، أنه عنى بذلك نوعا من أنواع الصواب، والظاهر محتمل جميعه", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}], "extra": [], "others": {"0": [{"id": 6977, "kinds": "غيره", "text": "قال ابنُ عطية (8/ 512): «وهي مكّيّة بإجماع».", "mawaqif": [{"taliq": 6977, "mi": 0, "aya": 0, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 512", "qawl": "", "nass": "وهي مكية بإجماع", "qawaid": [], "tabi": ""}]}, {"id": 6978, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (24/ 5) غير قول الحسن.", "mawaqif": []}], "10": [{"id": 6981, "kinds": "نقد،نقل", "text": "ذكر ابنُ عطية (8/ 514) في قوله: {لباسا} قولًا، وانتقده مستندًا إلى اللغة، فقال: «ويقال: جعله لِباسًا لأنه يطمس نور الأبصار، ويُلبس عليها الأشياء، والتصريف يُضعّف هذا القول، لأنه كان يجب أن يكون: مُلبسًا، ولا يقال: لِباسًا؛ إلا من لبس الثياب».", "mawaqif": [{"taliq": 6981, "mi": 0, "aya": 10, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "8/ 514", "qawl": "", "nass": "ويقال: جعله لباسا لأنه يطمس نور الأبصار، ويلبس عليها الأشياء، والتصريف يضعف هذا القول، لأنه كان يجب أن يكون: ملبسا، ولا يقال: لباسا؛ إلا من لبس الثياب", "qawaid": ["اللغة"], "tabi": ""}]}], "18": [{"id": 6984, "kinds": "ترجيح،توجيه،نقل", "text": "أفادت آثار السلف أنّ الصُّور: هو القَرْن الذي يُنفخ فيه لِبَعْث الناس. وقد ذكر ذلك ابنُ عطية (8/ 516)، ثم ذكر احتمالًا آخر، فقال: «ويحتمل هذا الموضع أن يكون» الصُّور «فيه جمع صورة، أي: يوم يرد الله فيه الأرواح إلى الأبدان، هذا قول بعضهم في الصُّورِ، وجوزه أبو حاتم». ثم رجّح -مستندًا إلى أقوال السلف، والنظائر- الأول، فقال: «والأول أشهر، وبه تظاهرت الآثار، وهو ظاهر كتاب الله تعالى في قوله: {ثُمَّ نُفِخَ فِيهِ أُخْرى} [الزمر: 68]».", "mawaqif": []}], "19": [{"id": 6985, "kinds": "خلاف،ترجيح،نقل", "text": "ذكر ابنُ عطية (8/ 516) في قوله: {فكانت أبوابا} قولين، فقال: «وقوله تعالى: {فكانت أبوابا} قيل: معناه: تتفطّر وتتشقّق حتى يكون فيها فتوح كالأبواب في الجدران. وقال آخرون -فيما حكى مكي بن أبي طالب-: الأبواب هنا فِلَق الخشب التي تُجعل أبوابًا لفتوح الجدران، أي: تتقطّع السماء قِطعًا صغارًا حتى تكون كألواح الأبواب. ورجّح القول الأول بقوله:» والقول الأول أحسن\". ولم يذكر مستندًا.", "mawaqif": [{"taliq": 6985, "mi": 0, "aya": 19, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "8/ 516", "qawl": "", "nass": "وقوله تعالى: {فكانت أبوابا} قيل: معناه: تتفطر وتتشقق حتى يكون فيها فتوح كالأبواب في الجدران. وقال آخرون -فيما حكى مكي بن أبي طالب-: الأبواب هنا فلق الخشب التي تجعل أبوابا لفتوح الجدران، أي: تتقطع السماء قطعا صغارا حتى تكون كألواح الأبواب. ورجح القول الأول بقوله:", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}]}], "23": [{"id": 6986, "kinds": "ترجيح،نقد،نقل", "text": "رجّح ابنُ جرير (24/ 22) -مستندًا إلى الأفصح لغة- قراءة مَن قرأ: {لابثين} بالألف، فقال: «وأفصح القراءتين وأصحّهما مخرجًا في العربية قراءةُ مَن قرأ ذلك بالألف؛ وذلك أنّ العرب لا تكاد توقع الصفة إذا جاءت على (فَعِل) فتُعمِلها في شيء وتنصبه بها، لا يكادون أن يقولوا: هذا رجل بَخِلٌ بماله، ولا عَسِرٌ علينا، ولا هو خَصِمٌ لنا. لأنّ (فَعِل) لا يأتي صفة إلا مدحًا أو ذمًّا، فلا يَعمل المدح والذم في غيره، وإذ أرادوا إعمال ذلك في الاسم أو غيره جعلوه فاعلًا، فقالوا: هو باخل بماله، وهو طامع فيما عندنا، فلذلك قلتّ: إنّ {لابثين} أصح مخرجًا في العربية وأفصح، ولم أحلّ قراءة مَن قرأ: «لَبِثِينَ» وإن كان غيرها أفصح؛ لأن العرب ربما أعملت المدح في الأسماء».\nوذكر ابنُ عطية (8/ 518) قراءة: «لَبِثِينَ»، ثم انتقدها -مستندًا إلى اللغة- عليها قائلًا: «وهي قراءة معترضة لأنّ (فَعِلًا) إنما يكون لما صار خُلُقًا؛ كحَذِر وفَرِق، وقد جاء شاذًّا فيما ليس بخُلُق».", "mawaqif": [{"taliq": 6986, "mi": 0, "aya": 23, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "24/ 22", "qawl": "", "nass": "وأفصح القراءتين وأصحهما مخرجا في العربية قراءة من قرأ ذلك بالألف؛ وذلك أن العرب لا تكاد توقع الصفة إذا جاءت على (فعل) فتعملها في شيء وتنصبه بها، لا يكادون أن يقولوا: هذا رجل بخل بماله، ولا عسر علينا، ولا هو خصم لنا. لأن (فعل) لا يأتي صفة إلا مدحا أو ذما، فلا يعمل المدح والذم في غيره، وإذ أرادوا إعمال ذلك في الاسم أو غيره جعلوه فاعلا، فقالوا: هو باخل بماله، وهو طامع فيما عندنا، فلذلك قلت: إن {لابثين} أصح مخرجا في العربية وأفصح، ولم أحل قراءة من قرأ: «لبثين", "qawaid": ["اللغة"], "tabi": ""}, {"taliq": 6986, "mi": 0, "aya": 23, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "8/ 518", "qawl": "", "nass": "لبثين", "qawaid": ["اللغة"], "tabi": ""}]}, {"id": 6988, "kinds": "نقد،نقل", "text": "ذكر ابنُ جرير (24/ 27) هذا القول، وانتقده مستندًا إلى دلالة العقل، فقال: «ولا معنى لهذا القول؛ لأن قوله: {لابثين فيها أحقابا} خبر، والأخبار لا يكون فيها نسخ، وإنما النسخ يكون في الأمر والنهي».\nوبنحوه قال ابنُ عطية (8/ 512).", "mawaqif": [{"taliq": 6988, "mi": 0, "aya": 23, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "24/ 27", "qawl": "", "nass": "ولا معنى لهذا القول؛ لأن قوله: {لابثين فيها أحقابا} خبر، والأخبار لا يكون فيها نسخ، وإنما النسخ يكون في الأمر والنهي", "qawaid": ["الدلالة العقلية"], "tabi": ""}, {"taliq": 6988, "mi": 0, "aya": 23, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 512", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن جرير"}]}], "27": [{"id": 6991, "kinds": "نقل", "text": "ذكر ابنُ عطية (8/ 521 - 521) القول بأنّ قوله: {يرجون} معناه: يَخافون، كما في آثار السلف، ثم ذكر قولًا آخر، فقال: «وقال غيره: الرجاء هنا على بابه، ولا رجاء إلا وهو مُقترن بخوف، ولا خوف إلا وهو مُقترن برجاء، فذكر أحد القسمين لأنّ المقصد العبارة عن تكذيبهم كأنه قال: إنهم كانوا لا يُصدِّقون بالحساب، فلذلك لا يَرجونه ولا يَخافونه».", "mawaqif": [{"taliq": 6991, "mi": 0, "aya": 27, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "8/ 521 - 521", "qawl": "بأن قوله", "nass": "وقال غيره: الرجاء هنا على بابه، ولا رجاء إلا وهو مقترن بخوف، ولا خوف إلا وهو مقترن برجاء، فذكر أحد القسمين لأن المقصد العبارة عن تكذيبهم كأنه قال: إنهم كانوا لا يصدقون بالحساب، فلذلك لا يرجونه ولا يخافونه", "qawaid": [], "tabi": ""}]}], "31": [{"id": 6992, "kinds": "ترجيح،نقل", "text": "ذكر ابنُ كثير (14/ 234) قول مجاهد، وقول ابن عباس قبله، ورجّح قول ابن عباس بالسياق، فقال: «الأظهر هاهنا قول ابن عباس؛ لأنه قال بعده: {حدائق} وهي البساتين من النخيل وغيرها، {وأعنابا وكواعب أترابا} أي: وحورًا كواعب».", "mawaqif": [{"taliq": 6992, "mi": 0, "aya": 31, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "14/ 234", "qawl": "مجاهد", "nass": "الأظهر هاهنا قول ابن عباس؛ لأنه قال بعده: {حدائق} وهي البساتين من النخيل وغيرها، {وأعنابا وكواعب أترابا} أي: وحورا كواعب", "qawaid": [], "tabi": ""}]}], "33": [{"id": 6993, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (24/ 38 - 39) غير قول عبد الرحمن بن زيد، وابن جُرَيْج، وقتادة، ومجاهد، وابن عباس.", "mawaqif": []}], "35": [{"id": 6995, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (24/ 43) غير قول عبد الرحمن، وقول قتادة.", "mawaqif": []}], "36": [{"id": 6996, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (8/ 522) أنّ جمهور المفسرين واللغويين ذكروا أنّ قوله: {حسابا} معناه: «محسبًا، أي: كافيًا من قولهم: أحسبني هذا الأمر، أي: كفاني، ومنه: حسبي الله». ثم ذكر عن مجاهد أنّ {حسابا} معناه: «مُقسَّطًا على الأعمال». ثم علّق بقوله: «لأنّ نفس دخول الجنة برحمة الله وتَفضُّله لا بعمل، والدرجات فيها والنِّعم على قدْر الأعمال، فإذا ضاعف الله لقوم حسناتهم بسبعمائة مثلًا، ومنهم المُكثر من الأعمال والمُقلّ؛ أخذ كلّ واحد سبعمائة بحسب عمله، وكذلك في كلّ تضعيف، فالحساب هنا هو بموازنة أعمال القوم».", "mawaqif": [{"taliq": 6996, "mi": 0, "aya": 36, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "8/ 522", "qawl": "", "nass": "محسبا، أي: كافيا من قولهم: أحسبني هذا الأمر، أي: كفاني، ومنه: حسبي الله", "qawaid": [], "tabi": ""}]}], "37": [{"id": 6997, "kinds": "ترجيح،نقل", "text": "رجّح ابنُ تيمية (6/ 454) -مستندًا إلى النظائر، والسنة- أنّ قوله: {لا يملكون منه خطابا} عام في جميع الخَلْق، فقال: «والصحيح: قول الجمهور والسلف أنّ هذا عام، كما قال في آية أخرى: {وخَشَعَت الأَصْواتُ لِلرَّحْمَنِ فَلا تَسْمَعُ إلّا هَمْسًا} [طه: 108]، وفي حديث التَّجلّي الذي في الصحيح لمّا ذكر مرورهم على الصراط قال صلى الله عليه وسلم: «ولا يَتكلّم أحد إلا الرُّسُل، ودعوى الرُّسُل: اللهم، سَلِّمْ سَلِّمْ». فهذا في وقت المرور على الصراط، وهو بعد الحساب والميزان، فكيف بما قبل ذلك؟!».", "mawaqif": [{"taliq": 6997, "mi": 0, "aya": 37, "alam": "ابن تيمية", "fil": "رجح", "kind": "ترجيح", "ref": "6/ 454", "qawl": "", "nass": "والصحيح: قول الجمهور والسلف أن هذا عام، كما قال في آية أخرى: {وخشعت الأصوات للرحمن فلا تسمع إلا همسا} [طه: 108]، وفي حديث التجلي الذي في الصحيح لما ذكر مرورهم على الصراط قال صلى الله عليه وسلم: «ولا يتكلم أحد إلا الرسل، ودعوى الرسل: اللهم، سلم سلم", "qawaid": ["القرآن والنظائر", "السنة"], "tabi": ""}]}, {"id": 6998, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (24/ 45 - 46) غير قول عبد الرحمن بن زيد، وقول قتادة، ومجاهد.", "mawaqif": []}], "38": [{"id": 6999, "kinds": "تعليق", "text": "علّق ابنُ كثير (8/ 236) على قول ابن مسعود، فقال: «وهذا قول غريب جدًّا».", "mawaqif": [{"taliq": 6999, "mi": 0, "aya": 38, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "8/ 236", "qawl": "ابن مسعود", "nass": "وهذا قول غريب جدا", "qawaid": [], "tabi": ""}]}, {"id": 7001, "kinds": "تعليق،نقل", "text": "ذكر ابنُ تيمية (6/ 455) قول مجاهد، وعلّق عليه قائلًا: «فعلى قول مجاهد يكون المستثنى مَن أتى بالكلم الطّيّب والعمل الصالح».", "mawaqif": [{"taliq": 7001, "mi": 0, "aya": 38, "alam": "ابن تيمية", "fil": "ذكر", "kind": "نقل", "ref": "6/ 455", "qawl": "مجاهد", "nass": "فعلى قول مجاهد يكون المستثنى من أتى بالكلم الطيب والعمل الصالح", "qawaid": [], "tabi": ""}]}], "40": [{"id": 7003, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (24/ 54) غير قول الحسن.", "mawaqif": []}, {"id": 7004, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (8/ 524) في قوله: {يا ليتني كنت ترابا} ما أفادته آثار السلف مِن أنّ هذا «تَمَنٍّ أن يكون شيئًا حقيرًا، لا يُحاسب، ولا يلتفتُ إليه». وعلّق عليه قائلًا: «وهذا قد تجده في الخائفين من المؤمنين». ثم ذكر في معنى الآية قولًا آخر، ووجّهه، فقال: «قال أبو القاسم بن حبيب: رأيتُ في بعض التفاسير أنّ الكافر هنا: إبليس، إذا رأى ما حصل للمؤمنين من بني آدم من الثواب، قال: يا ليتني كنتُ ترابًا، أي: كآدم الذي خُلق من تراب واحتقره هو أولًا».", "mawaqif": [{"taliq": 7004, "mi": 0, "aya": 40, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "8/ 524", "qawl": "", "nass": "تمن أن يكون شيئا حقيرا، لا يحاسب، ولا يلتفت إليه", "qawaid": [], "tabi": ""}]}]}, "athar": {"80921": {"num": 80921, "aya": 23, "qail": "أبي هريرة رفعه", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن أبي هريرة رفعه: {لابِثِينَ فِيها أحْقابًا}، قال: «الحُقُب ثمانون سنة»."}, "80927": {"num": 80927, "aya": 23, "qail": "أبي هريرة", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن أبي هريرة -من طريق شريك، عن عاصم بن أبي النجود، عن أبي صالح - {لابِثِينَ فِيها أحْقابًا}، قال: الحُقُب ثمانون سنة، والسنة ثلاثمائة وستون يومًا، واليوم كألف سنة مما تَعُدُّون."}, "80928": {"num": 80928, "aya": 23, "qail": "أبي هريرة", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن أبي هريرة -من طريق حماد بن سلمة، عن عاصم بن أبي النجود، عن أبي صالح - {لابِثِينَ فِيها أحْقابًا}، قال: الحُقُب ثمانون عامًا، اليوم منها كسُدس الدنيا."}, "80930": {"num": 80930, "aya": 23, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق أبي سنان- قال: الحُقُب ثمانون سنة."}, "80931": {"num": 80931, "aya": 23, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس، {لابِثِينَ فِيها أحْقابًا}، قال: سنين."}, "80934": {"num": 80934, "aya": 23, "qail": "بشير بن كعب", "tabaqa": "", "bab": "تفسير الآية", "text": "عن بشير بن كعب -من طريق إسحاق بن سُويد- في قوله: {لابِثِينَ فِيها أحْقابًا}، قال: بلغني: أنّ الحُقُب ثلاثمائة سنة، كلّ سنة ثلاثمائة وستون يومًا، كلّ يوم ألف سنة."}, "80935": {"num": 80935, "aya": 23, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن سعيد بن جُبَير -من طريق الأعمش- في قوله: {لابِثِينَ فِيها أحْقابًا}، قال: الحُقُب ثمانون سنة، السنة ثلاثمائة وستون يومًا، اليوم سنة أو ألف سنة."}, "80937": {"num": 80937, "aya": 23, "qail": "خالد بن معدان", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن خالد بن معدان -من طريق عامر بن جَشِيب- في قوله: {لابِثِينَ فِيها أحْقابًا}، وقوله: {إلّا ما شاءَ رَبُّكَ} [هود: 107]: إنهما في أهل التوحيد مِن أهل القِبلة."}, "80938": {"num": 80938, "aya": 23, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الحسن البصري -من طريق المبارك- {لابِثِينَ فِيها أحْقابًا}، قال: ليس لها أجل، كلّما مضى حُقُب دخل في الأخرى."}, "80939": {"num": 80939, "aya": 23, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الحسن البصري -من طريق سالم - قال: الحُقُب الواحد سبعون سنة، كلّ يوم منها ألف سنة."}, "80940": {"num": 80940, "aya": 23, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الحسن البصري -من طريق جعفر بن جسر، عن أبيه- قال: والحُقُب الواحد ثمانون ألف سنة، والسنة ثلاثمائة وستون يومًا، وكلّ يوم {عِنْدَ رَبِّكَ كَأَلْفِ سَنَةٍ مِمّا تَعُدُّونَ} [الحج: 47]."}, "80941": {"num": 80941, "aya": 23, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الحسن البصري -من طريق هشام- في قوله: {لابِثِينَ فِيها أحْقابًا}، قال: أما الأحقاب فلا يَدري أحد ما هي، وأما الحُقُب الواحد: فسبعون ألف سنة، كلّ يوم كألف سنة."}, "80942": {"num": 80942, "aya": 23, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق سعيد- {لابِثِينَ فِيها أحْقابًا}، قال: الأحقاب ما لا انقطاع له، كلّما مضى حُقُب جاء بعده حُقُب. قال: وذُكر لنا أنّ الحُقُب: ثمانون سنة من سني يوم القيامة."}, "80944": {"num": 80944, "aya": 23, "qail": "الربيع بن أنس", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الربيع بن أنس -من طريق أبي جعفر- {لابِثِينَ فِيها أحْقابًا}، قال: لا يَدري أحدُكم تلك الأحقاب، إلا أنّ الحُقُب الواحد ثمانون سنة، السنة ثلاثمائة وستون يومًا، اليوم الواحد مِقدار ألف سنة، والحُقُب الواحد ثمانية عشر ألف سنة."}, "80956": {"num": 80956, "aya": 25, "qail": "عبد الله بن عمرو", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عمرو -من طريق أبي مالك- أنه قال: أتدرون أيَّ شيء الغسّاق؟ قالوا: الله أعلم. قال: هو القِيح الغليظ، لو أنّ قطرة منه تُهراق بالمغرب لأَنتن أهل المشرق، ولو تُهراق بالمشرق لأَنتن أهل المغرب."}, "80957": {"num": 80957, "aya": 25, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- {إلّا حَمِيمًا وغَسّاقًا}، قال: الحميم: الحارّ الذي يَحرق. والغسّاق: الزمهرير البارد."}, "80958": {"num": 80958, "aya": 25, "qail": "أبي العالية الرياحي", "tabaqa": "تابعي", "bab": "", "text": "عن أبي العالية الرِّياحيّ -من طريق الربيع- {لا يَذُوقُونَ فِيها بَرْدًا ولا شَرابًا إلّا حَمِيمًا وغَسّاقًا}، قال: فاستثنى مِن الشراب الحميم، ومن البارد الغسّاق، وهو الزمهرير."}, "80959": {"num": 80959, "aya": 25, "qail": "أبي رزين مسعود بن مالك الأسدي", "tabaqa": "تابعي", "bab": "", "text": "عن أبي رَزِين [مسعود بن مالك الأسدي] ="}, "80960": {"num": 80960, "aya": 25, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "", "text": "وإبراهيم [النَّخْعي]-من طريق منصور- {إلّا حَمِيمًا وغَسّاقًا}، قالا: غُسالة أهل النار. وفي لفظ: ما يَسيل من صديدهم."}, "80961": {"num": 80961, "aya": 25, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "", "text": "عن إبراهيم النَّخْعي -من طريق منصور- في قوله: {حميما وغساقا}، قال: الغسّاق: ما يَنقطع مِن جلود أهل النار، وصديدهم."}, "80962": {"num": 80962, "aya": 25, "qail": "عبد الله بن بريدة", "tabaqa": "تابعي", "bab": "", "text": "عن عبد الله بن بُرَيْدة -من طريق صالح بن حيّان- قال: الغسّاق بالطُّخارية: هو المُنتِن."}, "80963": {"num": 80963, "aya": 25, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ليث- {إلّا حَمِيمًا وغَسّاقًا}، قال: لا يستطيعونه مِن بَرده."}, "80966": {"num": 80966, "aya": 25, "qail": "عطية بن سعد العوفي", "tabaqa": "تابعي", "bab": "", "text": "عن عطية بن سعد العَوفيّ -من طريق ابن إدريس، عن أبيه- في قوله: {حَمِيمًا وغَسّاقًا}، قال: هو الذي يَسيل مِن جلودهم."}, "80967": {"num": 80967, "aya": 25, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- قوله: {وغَسّاقًا}: كُنّا نُحدَّث أنّ الغسّاق: ما يَسيل مِن بين جِلده ولحمه."}, "80968": {"num": 80968, "aya": 25, "qail": "الربيع بن أنس", "tabaqa": "تابعي", "bab": "", "text": "عن الربيع بن أنس -من طريق أبي جعفر- {لا يَذُوقُونَ فِيها بَرْدًا ولا شَرابًا إلّا حَمِيمًا وغَسّاقًا}: فاستثنى من الشراب الحميم، ومن البارد الغسّاق."}, "80969": {"num": 80969, "aya": 25, "qail": "الربيع بن أنس", "tabaqa": "تابعي", "bab": "", "text": "عن الربيع بن أنس -من طريق أبي جعفر- قال: الغسّاق: الزمهرير."}, "80971": {"num": 80971, "aya": 25, "qail": "سفيان الثوري", "tabaqa": "تابع التابعين", "bab": "", "text": "عن سفيان [الثوري]-من طريق الضَّحّاك بن مخلد- أنه قال: بلَغني: أنّه ما يَسيل مِن دموعهم."}, "80972": {"num": 80972, "aya": 25, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {إلّا حَمِيمًا وغَسّاقًا}، قال: الحميم: دموع أعينهم في النار، يجتمع في خنادق النار، فيُسقَونه. والغسّاق: الصّديد الذي يَخرج من جلودهم، مما تَصهرهم النار في حياض يجتمع فيها، فيُسقَونه."}, "81014": {"num": 81014, "aya": 34, "qail": "أبي هريرة", "tabaqa": "صحابي", "bab": "", "text": "عن أبي هريرة -من طريق أبي رافع- {وكَأْسًا دِهاقًا}، قال: دمادُم."}, "81015": {"num": 81015, "aya": 34, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، قال: إذا كان فيها خمر فهي كأس، وإذا لم يكن فيها خمر فليس بكأس."}, "81016": {"num": 81016, "aya": 34, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، أنّ نافع بن الأزرق قال له: أخبِرني عن قوله: {وكَأْسًا دِهاقًا}. قال: الكأس: الخمر. والدِّهاق: المَلآن. قال: وهل تعرف العرب ذلك؟ قال: نعم، أما سمعتَ الشاعر وهو يقول: أتانا عامر يرجو قِرانًا … فأتْرَعْنا له كأسًا دهاقا؟."}, "81017": {"num": 81017, "aya": 34, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- قوله: {وكَأْسًا دِهاقًا}، يقول: مُمتلئًا."}, "81018": {"num": 81018, "aya": 34, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق مسلم بن نِسْطاس- في قوله: {وكَأْسًا دِهاقًا}، قال: هي المُمتلئة المُترَعة المُتتابعة، وربما سمعتُ العباسَ يقول: يا غلام، اسقِنا، وادْهَق لنا."}, "81019": {"num": 81019, "aya": 34, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عمرو بن دينار- أنه سُئل عن قوله: {وكَأْسًا دِهاقًا}. قال: دِراكًا."}, "81020": {"num": 81020, "aya": 34, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق أبي صالح- {وكَأْسًا دِهاقًا}، قال: مَلأى."}, "81022": {"num": 81022, "aya": 34, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "ومجاهد بن جبر -من طريق منصور- ="}, "81024": {"num": 81024, "aya": 34, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "والحسن البصري -من طريق أبي رجاء- ="}, "81025": {"num": 81025, "aya": 34, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "وقتادة بن دعامة -من طريق معمر-، مثله."}, "81026": {"num": 81026, "aya": 34, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- {وكَأْسًا دِهاقًا}، قال: المُتتابعة."}, "81029": {"num": 81029, "aya": 34, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق جابر- {وكَأْسًا}، قال: الكأْس: كلّ شيء يُشرب فيه الخمر."}, "81034": {"num": 81034, "aya": 34, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {وكَأْسًا دِهاقًا}، قال: مُترَعة: ملأى."}, "81036": {"num": 81036, "aya": 34, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {كَأْسًا دِهاقًا}، قال: الدِّهاق: المملوءة."}, "81053": {"num": 81053, "aya": 38, "qail": "ابن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن ابن عباس، أنّ النبيَّ صلى الله عليه وسلم، قال: «الروح جند من جنود الله، ليسوا بملائكة، لهم رؤوس وأيد وأرجل». ثم قرأ: {يَوْمَ يَقُومُ الرُّوحُ والمَلائِكَةُ صَفًّا}، قال: «هؤلاء جند، وهؤلاء جند»."}, "81054": {"num": 81054, "aya": 38, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن مسعود -من طريق عَلقمة- قال: الروح مَلَكٌ في السماء الرابعة، وهو أعظم من السموات والجبال ومن الملائكة، يُسبِّح كلَّ يوم اثني عشر ألف تسبيحة، يَخلُق الله من كلّ تسبيحة مَلَكًا مِن الملائكة، يجيء يوم القيامة صفًّا وحده."}, "81055": {"num": 81055, "aya": 38, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {يَوْمَ يَقُومُ الرُّوحُ}، قال: هو مَلَكٌ مِن أعظم الملائكة خَلْقًا."}, "81056": {"num": 81056, "aya": 38, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس: {الرُّوحُ} مَلَكٌ مِن الملائكة، ما خَلَق الله مخلوقًا أعظم منه، فإذا كان يوم القيامة قام وحده صفًّا، وقامت الملائكة كلّهم صفًّا واحدًا؛ فيكون عِظمُ خَلْقِه مثلَهم."}, "81057": {"num": 81057, "aya": 38, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق سِماك- قال: إنّ جبريل يوم القيامة القائم بين يدي الجبّار تُرْعَد فَرائصه فَرَقًا مِن عذاب الله، يقول: سبحانك، لا إله إلا أنت، ما عبدناك حقّ عبادتك. إنّ ما بين مَنكِبيه كما بين المشرق والمغرب، أما سمعتَ قول الله: {يَوْمَ يَقُومُ الرُّوحُ والمَلائِكَةُ صَفًّا}."}, "81058": {"num": 81058, "aya": 38, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق مجاهد- قال: {الرُّوحُ} أمْرٌ مِن أمْر الله، خَلْقٌ مِن خَلْق الله، صُوَرهم على صُوَر بني آدم، ما نزل من السماءِ مَلَكٌ إلا معه واحد من الروح."}, "81059": {"num": 81059, "aya": 38, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية- في قوله: {يَوْمَ يَقُومُ الرُّوحُ}، قال: يعني: حين تقوم أرواح الناس مع الملائكة فيما بين النفختين قبل أن تُردّ الأرواح إلى الأجساد."}, "81060": {"num": 81060, "aya": 38, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن نجيح- قال: الروح خَلْقٌ على صورة بني آدم."}, "81061": {"num": 81061, "aya": 38, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق مسلم- قال: الروح يأكلون، ولهم أيدٍ وأرجل ورؤوس، وليسوا بملائكة."}, "81062": {"num": 81062, "aya": 38, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضَّحّاك بن مُزاحِم -من طريق ثابت- في قوله: {يَوْمَ يَقُومُ الرُّوحُ}، قال: جبريل."}, "81063": {"num": 81063, "aya": 38, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضَّحّاك بن مُزاحِم، قال: الروح حاجب الله، فيقوم بين يدي الله يوم القيامة، وهو أعظم الملائكة، لو فَتح فاهُ لَوَسِع جميعَ الملائكة، والخَلْق إليه ينظرون، فمِن مَخافته لا يَرفعون طَرْفهم إلى مَن فوقه."}, "81065": {"num": 81065, "aya": 38, "qail": "عامر الشعبي", "tabaqa": "تابعي", "bab": "", "text": "عن عامر الشعبي -من طريق منصور- في قوله: {يَوْمَ يَقُومُ الرُّوحُ والمَلائِكَةُ صَفًّا}، قال: هما سِماطا ربِّ العالمين يوم القيامة؛ سِماط من الروح، وسِماط من الملائكة."}, "81068": {"num": 81068, "aya": 38, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق خُليد بن دَعلج- أنه قرأ: {يَوْمَ يَقُومُ الرُّوحُ والمَلائِكَةُ صَفًّا}، قال: الروح ههنا بنو آدم، يقومون يوم القيامة صفًّا."}, "81069": {"num": 81069, "aya": 38, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "قال الحسن البصري: {يَوْمَ يَقُومُ الرُّوحُ} يقوم روحُ كلِّ شيء في جسده."}, "81070": {"num": 81070, "aya": 38, "qail": "أبي صالح باذام", "tabaqa": "تابعي", "bab": "", "text": "عن أبي صالح [باذام]-من طريق إسماعيل بن أبي خالد- في قوله: {يَوْمَ يَقُومُ الرُّوحُ والمَلائِكَةُ صَفًّا}، قال: الروح خَلْقٌ كالناس، وليسوا بالناس، لهم أيدٍ وأرجل."}, "81073": {"num": 81073, "aya": 38, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق عبد الرزاق، عن معمر- في قوله تعالى: {يَوْمَ يَقُومُ الرُّوحُ}، قال: الروح هم بنو آدم."}, "81074": {"num": 81074, "aya": 38, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق ابن ثور، عن معمر- في قوله: {يَوْمَ يَقُومُ الرُّوحُ}: هذا مِمّا كان يكتمه ابن عباس."}, "81075": {"num": 81075, "aya": 38, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- كان أبي [زيد بن أسلم] يقول: الروح: القرآن. وقرأ: {وكَذَلِكَ أوْحَيْنا إلَيْكَ رُوحًا مِن أمْرِنا ما كُنْتَ تَدْرِي ما الكِتابُ ولا الإيمان} [الشورى: 52]."}, "81076": {"num": 81076, "aya": 38, "qail": "سليمان بن مهران الأعمش", "tabaqa": "تابعي", "bab": "", "text": "عن سليمان بن مهران الأعمش -من طريق المسعودي- في قوله: {يَوْمَ يَقُومُ الرُّوحُ والمَلائِكَةُ صَفًّا}، قال: الروح خَلْقٌ مِن خَلْق الله، يَضْعُفون على الملائكة أضعافًا، لهم أيدٍ وأرجل."}, "81081": {"num": 81081, "aya": 38, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {وقالَ صَوابًا}، قال: لا إله إلا الله."}, "81082": {"num": 81082, "aya": 38, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق سِماك- في قوله: {وقالَ صَوابًا}، قال: شهادة أن لا إله إلا الله."}, "81083": {"num": 81083, "aya": 38, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {وقالَ صَوابًا}، قال: حقًّا في الدنيا، وعَمِل به."}, "81086": {"num": 81086, "aya": 38, "qail": "أبي صالح باذام", "tabaqa": "تابعي", "bab": "", "text": "عن أبي صالح [باذام]-من طريق إسماعيل بن أبي خالد- في قوله: {إلّا مَن أذِنَ لَهُ الرَّحْمَنُ وقالَ صَوابًا}، قال: لا إله إلا الله."}, "81087": {"num": 81087, "aya": 38, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق خُليد- يقول: وقرأ: {لا يَتَكَلَّمُونَ إلّا مَن أذِنَ لَهُ الرَّحْمَنُ وقالَ صَوابًا} في الدنيا."}, "80852": {"num": 80852, "aya": 14, "qail": "قتادة", "tabaqa": "تابعي", "bab": "قراءات", "text": "عن قتادة -من طريق أبي عوانة- قال: في مصحف الفضل بن عباس: (وأَنزَلْنا بِالمُعْصِراتِ مَآءً ثَجّاجًا)."}, "80853": {"num": 80853, "aya": 14, "qail": "قتادة", "tabaqa": "تابعي", "bab": "قراءات", "text": "عن قتادة، قال: في قراءة ابن عباس: (وأَنزَلْنا بِالمُعْصِراتِ): بالرياح."}, "80854": {"num": 80854, "aya": 14, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "قراءات", "text": "عن مجاهد بن جبر: (وأَنزَلْنا بِالمُعْصِراتِ): الريح. وكذلك كان يقرؤها: (بِالمُعْصِراتِ مَآءً ثَجّاجًا): منصبًّا."}, "80861": {"num": 80861, "aya": 14, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق عطية- {وأَنْزَلْنا مِنَ المُعْصِراتِ}، قال: الرياح."}, "80862": {"num": 80862, "aya": 14, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {وأَنْزَلْنا مِنَ المُعْصِراتِ}، قال: السحاب."}, "80863": {"num": 80863, "aya": 14, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس، أنّ نافع بن الأزرق قال له: أخبِرني عن قوله: {وأَنْزَلْنا مِنَ المُعْصِراتِ}. قال: السحاب يَعصِر بعضها بعضًا، فيَخرج الماء مِن بين السحابتين. قال: وهل تعرف العرب ذلك؟ قال: نعم، أما سمعتَ النّابغة وهو يقول: تجُرُّ بها الأرواح من بين شمأل … وبين صَباها المعصراتُ الدَّوامسُ؟."}, "80866": {"num": 80866, "aya": 14, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {وأَنْزَلْنا مِنَ المُعْصِراتِ}، قال: الريح."}, "80870": {"num": 80870, "aya": 14, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق معمر- {وأَنْزَلْنا مِنَ المُعْصِراتِ}، قال: من السماء، وبعضهم يقول: الريح."}, "80872": {"num": 80872, "aya": 14, "qail": "سفيان الثوري", "tabaqa": "تابع التابعين", "bab": "تفسير الآية", "text": "عن سفيان [الثوري]-من طريق مهران- {مِنَ المُعْصِرات}، قال: المُعصرات: السحاب."}, "80873": {"num": 80873, "aya": 14, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "تفسير الآية", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {وأَنْزَلْنا مِنَ المُعْصِرات}، قال: المُعصرات: الرياح. وقرأ قوله: {اللَّهُ الَّذِي يُرْسِلُ الرِّياحَ فَتُثِيرُ سَحابًا} إلى آخر الآية [الروم: 48]."}, "80874": {"num": 80874, "aya": 14, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {ماءً ثَجّاجًا}، قال: مُنصَبًّا."}, "80875": {"num": 80875, "aya": 14, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، أنّ نافع بن الأزرق قال له: أخبِرني عن قوله: {ثَجّاجًا}. قال: الثَّجاج: الكثير الذي يَنبتُ منه الزرع. قال: وهل تعرف العرب ذلك؟ قال: نعم، أما سمعتَ أبا ذُؤيب يقول: سقى أُمَّ عمرو كلَّ آخر ليلة … غمائمُ سُود ماؤهن ثجيج؟."}, "80876": {"num": 80876, "aya": 14, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {ماء ثجاجا}، قال: مُنصبًّا يَنصب."}, "80879": {"num": 80879, "aya": 14, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق معمر- {ماءً ثَجّاجًا}، قال: الثّجاج: المُنصَبُّ."}, "80880": {"num": 80880, "aya": 14, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "قال قتادة بن دعامة: {ماءً ثَجّاجًا} مُتتابعًا يتلو بعضه بعضًا."}, "80883": {"num": 80883, "aya": 14, "qail": "سفيان الثوري", "tabaqa": "تابع التابعين", "bab": "", "text": "عن سفيان [الثوري]-من طريق مهران- {ماءً ثَجّاجًا}، قال: مُتتابعًا."}, "80884": {"num": 80884, "aya": 14, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {ماءً ثَجّاجًا}، قال: كثيرًا."}}, "n_athar": {"0": 17, "3": 7, "6": 5, "7": 4, "8": 2, "9": 1, "10": 2, "11": 3, "12": 2, "13": 7, "14": 33, "15": 1, "16": 8, "17": 2, "18": 4, "19": 1, "20": 5, "21": 8, "22": 3, "23": 31, "24": 7, "25": 19, "26": 9, "27": 5, "28": 1, "29": 1, "30": 7, "31": 5, "32": 2, "33": 10, "34": 23, "35": 4, "36": 5, "37": 7, "38": 37, "39": 4, "40": 20}, "muh": ["ابن جرير", "ابن عطية", "ابن كثير", "ابن تيمية", "ابن القيم"], "ords": ["الأول", "الثاني", "الثالث", "الرابع", "الخامس", "السادس", "السابع", "الثامن", "التاسع", "العاشر"], "index": "فهرس.html"});